script.lang:
               -- First, drop any existing constraint without knowing its exact name
-- This uses a more compatible approach without DO block
CREATE OR REPLACE FUNCTION drop_created_by_fk() RETURNS void AS $$
DECLARE
    constraint_record RECORD;
BEGIN
    FOR constraint_record IN
        SELECT con.conname AS constraint_name
        FROM pg_constraint con
                 JOIN pg_class cl ON con.conrelid = cl.oid
                 JOIN pg_attribute attr ON attr.attrelid = cl.oid AND attr.attnum = ANY(con.conkey)
        WHERE cl.relname = 'amp_indicator_layer'
          AND attr.attname = 'created_by'
          AND con.contype = 'f'
        LOOP
            EXECUTE 'ALTER TABLE amp_indicator_layer DROP CONSTRAINT ' || constraint_record.constraint_name;
        END LOOP;
END;
$$ LANGUAGE plpgsql;

SELECT drop_created_by_fk();
DROP FUNCTION drop_created_by_fk();

-- Then add the new constraint
ALTER TABLE amp_indicator_layer
    ADD CONSTRAINT fk_created_by_user
        FOREIGN KEY (created_by) REFERENCES "user"(id);
